const params = [
  { key: "waves", label: "Waves", min: 1, max: 16, step: 1, default: 5, integer: true },
  { key: "width", label: "Width", min: 20, max: 800, step: 1, default: 170 },
  { key: "amplitude", label: "Amplitude", min: 1, max: 200, step: 1, default: 34 }
];

const build = (args) => {
  const waves = Math.max(1, Math.round(args.waves));
  const width = Math.max(1, args.width);
  const amplitude = args.amplitude;
  const step = width / waves;
  const anchors = [];
  for (let i = 0; i <= waves; i++) {
    const x = -width / 2 + i * step;
    const y = i % 2 === 0 ? -amplitude : amplitude;
    anchors.push({
      p: { x: x, y: y },
      hIn: i === 0 ? null : { x: x - step * 0.4, y: y },
      hOut: i === waves ? null : { x: x + step * 0.4, y: y },
      t: "symmetric"
    });
  }
  return [{ anchors: anchors, closed: false }];
};

return { params, build };
